<?php
$page_title='ศูนย์ผู้ขาย';require_once __DIR__.'/includes/auth_check.php';requireSeller();require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/image_upload.php';$db=(new Database())->getConnection();$message='';$error='';$sellerId=(int)$_SESSION['user_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf(false);if(($_POST['action']??'')==='add_product'){try{$name=trim((string)$_POST['name']);$category=(int)$_POST['category_id'];$price=(float)$_POST['price'];$stock=(int)$_POST['stock_quantity'];$desc=trim((string)$_POST['description']);if(mb_strlen($name)<2||$category<1||$price<=0||$stock<0)throw new RuntimeException('กรุณากรอกข้อมูลสินค้าให้ครบถ้วน');$image=saveProductImageUpload($_FILES['product_image']??[]);$stmt=$db->prepare("INSERT INTO products(category_id,seller_id,name,description,price,stock_quantity,image_url,is_featured,approval_status) VALUES (?,?,?,?,?,?,?,0,'pending')");$stmt->execute([$category,$sellerId,$name,$desc,$price,$stock,$image]);createRoleNotification($db,'admin','seller','มีสินค้าใหม่รอตรวจสอบ','สินค้า '.$name.' จากผู้ขายรอตรวจสอบ',BASE_URL.'admin/seller-products.php');$message='ส่งสินค้าเข้าตรวจสอบแล้ว';}catch(Throwable $e){$error=$e->getMessage();}}}
$categories=$db->query('SELECT id,name FROM categories ORDER BY id')->fetchAll();$products=$db->prepare('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE p.seller_id=? ORDER BY p.created_at DESC');$products->execute([$sellerId]);$products=$products->fetchAll();$stats=['products'=>count($products),'pending'=>0,'approved'=>0,'low_stock'=>0,'orders'=>0];foreach($products as $product){$stats[$product['approval_status']]++;if((int)$product['stock_quantity']<=5)$stats['low_stock']++;}$orderStats=$db->prepare("SELECT COUNT(DISTINCT o.id) FROM orders o JOIN order_items oi ON oi.order_id=o.id JOIN products p ON p.id=oi.product_id LEFT JOIN order_fulfillments f ON f.order_id=o.id AND f.seller_id=? WHERE p.seller_id=? AND o.order_status<>'cancelled' AND COALESCE(f.status,'pending') IN ('pending','accepted','packing')");$orderStats->execute([$sellerId,$sellerId]);$stats['orders']=(int)$orderStats->fetchColumn();
require_once __DIR__.'/includes/header.php';
?><link rel="stylesheet" href="<?php echo BASE_URL; ?>assets/css/seller.css"><div class="seller-page"><div class="container"><section class="seller-hero seller-dashboard-hero"><div><p class="eyebrow">SELLER CENTER</p><h1>ร้านของคุณ<br>พร้อมเริ่มขายแล้ว</h1><p>เพิ่มสินค้า ตั้งสต็อก และรอทีมงานตรวจเพื่อให้แสดงบนหน้าร้าน</p></div><aside><span><i class="fa-solid fa-chart-line"></i></span><strong>สถานะร้าน<br>เปิดใช้งานแล้ว</strong></aside></section><section class="seller-stats"><div><small>สินค้าทั้งหมด</small><strong><?php echo $stats['products']; ?></strong></div><div><small>รอตรวจสอบ</small><strong><?php echo $stats['pending']; ?></strong></div><div><small>ขึ้นขายแล้ว</small><strong><?php echo $stats['approved']; ?></strong></div></section><section class="seller-application seller-dashboard"><aside><p class="eyebrow">ADD PRODUCT</p><h2>เพิ่มสินค้า<br>ชิ้นแรก</h2><p>หลังบันทึก สินค้าจะรอตรวจสอบก่อนแสดงให้ลูกค้าเห็น</p></aside><form class="seller-form" method="POST" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken()); ?>"><input type="hidden" name="action" value="add_product"><header><p class="eyebrow">PRODUCT DETAILS</p><h2>ข้อมูลสินค้า</h2></header><?php if($message): ?><p class="seller-success"><?php echo e($message); ?></p><?php endif;if($error): ?><p class="seller-error"><?php echo e($error); ?></p><?php endif; ?><div class="seller-fields"><label class="full">ชื่อสินค้า<input name="name" required maxlength="200"></label><label>หมวดสินค้า<select name="category_id" required><?php foreach($categories as $category): ?><option value="<?php echo (int)$category['id']; ?>"><?php echo e($category['name']); ?></option><?php endforeach; ?></select></label><label>ราคา (บาท)<input type="number" name="price" required min="0.01" step="0.01"></label><label>จำนวนสต็อก<input type="number" name="stock_quantity" required min="0" value="0"></label><label class="full">อัปโหลดรูปสินค้า<input type="file" name="product_image" required accept="image/jpeg,image/png,image/webp"><small>JPG, PNG หรือ WebP เท่านั้น ขนาดไม่เกิน 3 MB</small></label><label class="full">รายละเอียดสินค้า<textarea name="description" rows="4" maxlength="3000"></textarea></label></div><footer><span>สินค้าจะขึ้นหน้าร้านหลังแอดมินอนุมัติ</span><button class="btn btn-primary">ส่งสินค้าเข้าตรวจ <i class="fa-solid fa-paper-plane"></i></button></footer></form></section><section class="admin-panel seller-product-list"><header class="admin-panel-header"><div><h2>สินค้าของฉัน</h2><p>ติดตามสถานะสินค้าและสต็อก</p></div></header><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>สินค้า</th><th>ราคา</th><th>สต็อก</th><th>สถานะ</th></tr></thead><tbody><?php if(!$products): ?><tr><td colspan="4" class="admin-empty">ยังไม่มีสินค้า เริ่มเพิ่มสินค้าได้ด้านบน</td></tr><?php endif;foreach($products as $product): ?><tr><td><strong><?php echo e($product['name']); ?></strong><span class="cell-subtitle"><?php echo e($product['category_name']); ?></span></td><td><?php echo formatCurrency($product['price']); ?></td><td><?php echo (int)$product['stock_quantity']; ?></td><td><span class="status-badge <?php echo $product['approval_status']==='approved'?'paid':($product['approval_status']==='rejected'?'cancelled':'pending'); ?>"><?php echo e($product['approval_status']); ?></span><?php if($product['admin_note']): ?><span class="cell-subtitle"><?php echo e($product['admin_note']); ?></span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></div></div><?php require_once __DIR__.'/includes/footer.php'; ?>
